{"file_path":"src/lcs.js","content":"/**
 * Longest common subsequence over whole lines, compared as exact strings.
 *
 * Among the equally long subsequences the walk picks the one whose matches
 * come earliest: starting from the front of both documents, a match is taken
 * whenever the two current lines are equal, and otherwise the side whose
 * remaining subsequence is at least as long as the other's is advanced, with
 * the first document (the base) advanced when the two tie.
 */
export function lcsMatches (a, b) {
  const n = a.length
  const m = b.length

  // dp[i][j] is the length of the longest common subsequence of a[i..] and b[j..].
  const dp = new Array(n + 1)
  for (let i = 0; i <= n; i++) dp[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    const rowNext = dp[i + 1]
    const row = dp[i]
    for (let j = m - 1; j >= 0; j--) {
      if (a[i] === b[j]) {
        row[j] = rowNext[j + 1] + 1
      } else {
        const skipA = rowNext[j]
        const skipB = row[j + 1]
        row[j] = skipA >= skipB ? skipA : skipB
      }
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (a[i] === b[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  return matches
}

/**
 * The stretches the subsequence does not cover, each a run of base lines
 * replaced by a run of the side's lines.
 */
export function findChanges (base, side) {
  const matches = lcsMatches(base, side)
  const changes = []
  let baseIdx = 0
  let sideIdx = 0

  const push = (baseEnd, sideEnd) => {
    if (baseIdx !== baseEnd || sideIdx !== sideEnd) {
      changes.push({ baseStart: baseIdx, baseEnd, sideStart: sideIdx, sideEnd })
    }
  }

  for (const [bIdx, sIdx] of matches) {
    push(bIdx, sIdx)
    baseIdx = bIdx + 1
    sideIdx = sIdx + 1
  }
  push(base.length, side.length)

  return changes
}
"}

