function arraysEqual (a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

/**
 * The lines one side puts in place of a region: from the smallest start of
 * that side's changes moved back by however far the region begins before
 * those changes do in the base, to the largest end of its own changes moved
 * forward by however far the region ends after them.
 */
function sideLines (doc, changes, regionStart, regionEnd) {
  let minBaseStart = Infinity
  let maxBaseEnd = -Infinity
  let minSideStart = Infinity
  let maxSideEnd = -Infinity
  for (const c of changes) {
    if (c.baseStart < minBaseStart) minBaseStart = c.baseStart
    if (c.baseEnd > maxBaseEnd) maxBaseEnd = c.baseEnd
    if (c.sideStart < minSideStart) minSideStart = c.sideStart
    if (c.sideEnd > maxSideEnd) maxSideEnd = c.sideEnd
  }
  const start = minSideStart - (minBaseStart - regionStart)
  const end = maxSideEnd + (regionEnd - maxBaseEnd)
  return doc.slice(start, end)
}

/**
 * Split the base into stable regions and regions of overlapping changes, and
 * resolve each of the latter to one side's lines or to a conflict.
 */
export function buildRegions (mine, base, theirs) {
  const all = []
  for (const c of findChanges(base, mine)) all.push({ ...c, side: 'mine' })
  for (const c of findChanges(base, theirs)) all.push({ ...c, side: 'theirs' })
  // Ordered by where they start in the base, mine before theirs on a tie.
  all.sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const regions = []
  let stableStart = 0
  let i = 0
  while (i < all.length) {
    const first = all[i]
    if (stableStart < first.baseStart) {
      regions.push({ type: 'stable', lines: base.slice(stableStart, first.baseStart) })
    }

    const regionStart = first.baseStart
    let regionEnd = first.baseEnd
    const group = [first]
    i++
    while (i < all.length && all[i].baseStart <= regionEnd) {
      if (all[i].baseEnd > regionEnd) regionEnd = all[i].baseEnd
      group.push(all[i])
      i++
    }

    const baseLines = base.slice(regionStart, regionEnd)
    const mineChanges = group.filter(c => c.side === 'mine')
    const theirsChanges = group.filter(c => c.side === 'theirs')
    const mineLines = mineChanges.length
      ? sideLines(mine, mineChanges, regionStart, regionEnd)
      : baseLines
    const theirsLines = theirsChanges.length
      ? sideLines(theirs, theirsChanges, regionStart, regionEnd)
      : baseLines

    if (arraysEqual(mineLines, theirsLines)) {
      regions.push({ type: group.length > 1 ? 'both' : first.side, lines: mineLines })
    } else if (arraysEqual(mineLines, baseLines)) {
      regions.push({ type: 'theirs', lines: theirsLines })
    } else if (arraysEqual(theirsLines, baseLines)) {
      regions.push({ type: 'mine', lines: mineLines })
    } else {
      regions.push({ type: 'conflict', mineLines, baseLines, theirsLines })
    }

    stableStart = regionEnd
  }

  if (stableStart < base.length) {
    regions.push({ type: 'stable', lines: base.slice(stableStart) })
  }
  return regions
}

export function renderMerge (regions, withBase) {
  const out = []
  let conflict = false
  for (const region of regions) {
    if (region.type === 'conflict') {
      conflict = true
      out.push('<<<<<<< mine')
      out.push(...region.mineLines)
      if (withBase) {
        out.push('||||||| base')
        out.push(...region.baseLines)
      }
      out.push('=======')
      out.push(...region.theirsLines)
      out.push('>>>>>>> theirs')
    } else {
      out.push(...region.lines)
    }
  }
  return { lines: out, conflict }
