export function renderRegions (regions) {
  const out = []
  let conflict = false
  for (const region of regions) {
    if (region.type === 'conflict') {
      conflict = true
      out.push(`conflict mine=${region.mineLines.length} base=${region.baseLines.length} theirs=${region.theirsLines.length}`)
    } else {
      out.push(`${region.type} ${region.lines.length}`)
    }
  }
  return { lines: out, conflict }
}
