#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'fs'

const mode = process.argv[2]
if (!['merge', 'merge2', 'regions'].includes(mode)) {
  process.stderr.write('error: usage: cli.js merge|merge2|regions\n')
  process.exit(2)
}

// Read all input from stdin
const input = readFileSync(0, 'utf8')

// Parse input documents
const lines = input.split('\n')
// Drop empty tail from trailing newline
if (lines.length > 0 && lines[lines.length - 1] === '') {
  lines.pop()
}

const parts = []
let currentPart = []
for (const line of lines) {
  if (line === '%%%') {
    parts.push(currentPart)
    currentPart = []
  } else {
    currentPart.push(line)
  }
}
parts.push(currentPart)

if (parts.length !== 3) {
  process.stderr.write('error: expected three parts separated by %%%\n')
  process.exit(2)
}

const [mine, base, theirs] = parts

// LCS algorithm with specific tie-breaking rules
function computeLCS(a, b) {
  const n = a.length
  const m = b.length

  // dp[i][j] = length of LCS of a[0..i-1] and b[0..j-1]
  const dp = Array(n + 1).fill(null).map(() => Array(m + 1).fill(0))

  for (let i = 1; i <= n; i++) {
    for (let j = 1; j <= m; j++) {
      if (a[i - 1] === b[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
      }
    }
  }

  // Backtrack with specific tie-breaking: prefer earliest matches
  // When dp[i-1][j] === dp[i][j-1], prefer advancing a (moving up)
  const result = []
  let i = n, j = m
  while (i > 0 && j > 0) {
    if (a[i - 1] === b[j - 1]) {
      result.unshift([i - 1, j - 1])
      i--
      j--
    } else if (dp[i - 1][j] >= dp[i][j - 1]) {
      i--
    } else {
      j--
    }
  }

  return result
}

// Find changes by comparing side to base
function findChanges(side, base) {
  const matches = computeLCS(base, side)

  const changes = []
  let baseIdx = 0
  let sideIdx = 0

  for (const [bIdx, sIdx] of matches) {
    // If there's a gap, that's a change
    if (bIdx > baseIdx || sIdx > sideIdx) {
      changes.push({
        baseStart: baseIdx,
        baseEnd: bIdx,
        sideStart: sideIdx,
        sideEnd: sIdx
      })
    }
    baseIdx = bIdx + 1
    sideIdx = sIdx + 1
  }

  // Handle the tail
  if (baseIdx < base.length || sideIdx < side.length) {
    changes.push({
      baseStart: baseIdx,
      baseEnd: base.length,
      sideStart: sideIdx,
      sideEnd: side.length
    })
  }

  // Filter out empty changes
  return changes.filter(c => c.baseStart !== c.baseEnd || c.sideStart !== c.sideEnd)
}

const mineChanges = findChanges(mine, base).map(c => ({ ...c, side: 'mine' }))
const theirsChanges = findChanges(theirs, base).map(c => ({ ...c, side: 'theirs' }))

// Combine and sort changes: by base start, then mine before theirs
const allChanges = [...mineChanges, ...theirsChanges].sort((a, b) => {
  if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
  if (a.side === b.side) return 0
  return a.side === 'mine' ? -1 : 1
})

// Build regions by merging overlapping changes
const regions = []
let stableStart = 0

let changeIdx = 0
while (changeIdx < allChanges.length) {
  const firstChange = allChanges[changeIdx]

  // Add stable region before this change if any
  if (stableStart < firstChange.baseStart) {
    regions.push({
      type: 'stable',
      baseStart: stableStart,
      baseEnd: firstChange.baseStart,
      lines: base.slice(stableStart, firstChange.baseStart)
    })
  }

  // Collect all changes that touch this region
  let regionStart = firstChange.baseStart
  let regionEnd = firstChange.baseEnd
  const regionChanges = [firstChange]

  changeIdx++
  while (changeIdx < allChanges.length) {
    const nextChange = allChanges[changeIdx]
    if (nextChange.baseStart <= regionEnd) {
      regionChanges.push(nextChange)
      regionEnd = Math.max(regionEnd, nextChange.baseEnd)
      changeIdx++
    } else {
      break
    }
  }

  // Resolve the region
  const mineRegionChanges = regionChanges.filter(c => c.side === 'mine')
  const theirsRegionChanges = regionChanges.filter(c => c.side === 'theirs')

  const regionBaseStart = regionStart
  const regionBaseEnd = regionEnd
  const regionBase = base.slice(regionBaseStart, regionBaseEnd)

  let region
  if (mineRegionChanges.length === 0) {
    // Only theirs changed
    const minTheirsStart = Math.min(...theirsRegionChanges.map(c => c.baseStart))
    const maxTheirsEnd = Math.max(...theirsRegionChanges.map(c => c.baseEnd))
    const minTheirsSideStart = Math.min(...theirsRegionChanges.map(c => c.sideStart))
    const maxTheirsSideEnd = Math.max(...theirsRegionChanges.map(c => c.sideEnd))

    region = {
      type: 'theirs',
      baseStart: regionBaseStart,
      baseEnd: regionBaseEnd,
      lines: theirs.slice(minTheirsSideStart, maxTheirsSideEnd)
    }
  } else if (theirsRegionChanges.length === 0) {
    // Only mine changed
    const minMineStart = Math.min(...mineRegionChanges.map(c => c.baseStart))
    const maxMineEnd = Math.max(...mineRegionChanges.map(c => c.baseEnd))
    const minMineSideStart = Math.min(...mineRegionChanges.map(c => c.sideStart))
    const maxMineSideEnd = Math.max(...mineRegionChanges.map(c => c.sideEnd))

    region = {
      type: 'mine',
      baseStart: regionBaseStart,
      baseEnd: regionBaseEnd,
      lines: mine.slice(minMineSideStart, maxMineSideEnd)
    }
  } else {
    // Both sides changed - need to compute their replacements
    const minMineStart = Math.min(...mineRegionChanges.map(c => c.baseStart))
    const maxMineEnd = Math.max(...mineRegionChanges.map(c => c.baseEnd))
    const minMineSideStart = Math.min(...mineRegionChanges.map(c => c.sideStart))
    const maxMineSideEnd = Math.max(...mineRegionChanges.map(c => c.sideEnd))

    const minTheirsStart = Math.min(...theirsRegionChanges.map(c => c.baseStart))
    const maxTheirsEnd = Math.max(...theirsRegionChanges.map(c => c.baseEnd))
    const minTheirsSideStart = Math.min(...theirsRegionChanges.map(c => c.sideStart))
    const maxTheirsSideEnd = Math.max(...theirsRegionChanges.map(c => c.sideEnd))

    // Compute offset from region start to earliest change
    const offsetBefore = regionBaseStart - Math.min(minMineStart, minTheirsStart)
    const offsetAfter = Math.max(maxMineEnd, maxTheirsEnd) - regionBaseEnd

    // Each side's replacement lines
    const mineLinesStart = minMineSideStart - offsetBefore
    const mineLinesEnd = maxMineSideEnd + offsetAfter
    const theirsLinesStart = minTheirsSideStart - offsetBefore
    const theirsLinesEnd = maxTheirsSideEnd + offsetAfter

    const mineLines = mine.slice(Math.max(0, mineLinesStart), Math.min(mine.length, mineLinesEnd))
    const theirsLines = theirs.slice(Math.max(0, theirsLinesStart), Math.min(theirs.length, theirsLinesEnd))

    // Check if it's the same change or a conflict
    if (arraysEqual(mineLines, theirsLines)) {
      region = {
        type: 'both',
        baseStart: regionBaseStart,
        baseEnd: regionBaseEnd,
        lines: mineLines
      }
    } else if (arraysEqual(mineLines, regionBase)) {
      region = {
        type: 'theirs',
        baseStart: regionBaseStart,
        baseEnd: regionBaseEnd,
        lines: theirsLines
      }
    } else if (arraysEqual(theirsLines, regionBase)) {
      region = {
        type: 'mine',
        baseStart: regionBaseStart,
        baseEnd: regionBaseEnd,
        lines: mineLines
      }
    } else {
      region = {
        type: 'conflict',
        baseStart: regionBaseStart,
        baseEnd: regionBaseEnd,
        mineLines: mineLines,
        theirsLines: theirsLines,
        baseLines: regionBase
      }
    }
  }

  regions.push(region)
  stableStart = regionEnd
}

// Add final stable region if any
if (stableStart < base.length) {
  regions.push({
    type: 'stable',
    baseStart: stableStart,
    baseEnd: base.length,
    lines: base.slice(stableStart, base.length)
  })
}

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false
  }
  return true
}

// Output based on mode
let hasConflict = false
const output = []

if (mode === 'merge' || mode === 'merge2') {
  for (const region of regions) {
    if (region.type === 'stable' || region.type === 'mine' || region.type === 'theirs' || region.type === 'both') {
      output.push(...region.lines)
    } else if (region.type === 'conflict') {
      hasConflict = true
      output.push('<<<<<<< mine')
      output.push(...region.mineLines)
      if (mode === 'merge') {
        output.push('||||||| base')
        output.push(...region.baseLines)
      }
      output.push('=======')
      output.push(...region.theirsLines)
      output.push('>>>>>>> theirs')
    }
  }

  process.stdout.write(output.map(line => line + '\n').join(''))
} else if (mode === 'regions') {
  for (const region of regions) {
    const lineCount = region.lines ? region.lines.length : 0
    if (region.type === 'stable') {
      output.push(`stable ${lineCount}`)
    } else if (region.type === 'mine') {
      output.push(`mine ${lineCount}`)
    } else if (region.type === 'theirs') {
      output.push(`theirs ${lineCount}`)
    } else if (region.type === 'both') {
      output.push(`both ${lineCount}`)
    } else if (region.type === 'conflict') {
      hasConflict = true
      const mineCount = region.mineLines.length
      const baseCount = region.baseLines.length
      const theirsCount = region.theirsLines.length
      output.push(`conflict mine=${mineCount} base=${baseCount} theirs=${theirsCount}`)
    }
  }

  process.stdout.write(output.join('\n') + (output.length > 0 ? '\n' : ''))
}

process.exit(hasConflict ? 1 : 0)

